"""Golden data for StintTracker + event detection, generated by the REAL gt7telem.udp.
Run from the gt7telem-package folder:  python make_fixtures2.py <out.json>"""
import json, sys, types
sys.path.insert(0, "src")
from gt7telem import udp

def snap_clean(s):
    return {k: (dict(v) if isinstance(v, dict) else v) for k, v in s.items()}

def stint_case():
    st = udp.StintTracker()
    steps = []
    fuel = 60.0
    lap = 1
    last_ms = 0
    laps_ms = [0, 108400, 107900, 107750, 107800, 108300, 109400, 110500, 111900, 112100]
    # per lap: 12 samples; fuel burn varies; refuel before lap 7
    for lap in range(1, 10):
        burn = 2.9 + 0.1 * (lap % 3)
        for k in range(12):
            if lap == 7 and k == 0:
                fuel += 30.0
            fuel -= burn / 12
            temps = [88 + k, 90 + k, 84 + k, 95 + k] if k % 2 == 0 else [58, 90, 84, 95]
            st.update(lap, 12, fuel, laps_ms[lap - 1] if lap > 1 else 0, temps, 120.0)
            steps.append({"args": [lap, 12, fuel, laps_ms[lap - 1] if lap > 1 else 0, temps, 120.0],
                          "snap": snap_clean(st.snapshot())})
    st.reset_stint()
    steps.append({"reset_stint": True, "snap": snap_clean(st.snapshot())})
    # restart: lap goes backwards
    st.update(1, 12, 50.0, 0, [90, 90, 90, 90], 100.0)
    steps.append({"args": [1, 12, 50.0, 0, [90, 90, 90, 90], 100.0], "snap": snap_clean(st.snapshot())})
    # free run: total laps 0
    st2 = udp.StintTracker()
    out2 = []
    f = 80.0
    for lap in range(1, 6):
        for k in range(5):
            f -= 0.5
            st2.update(lap, 0, f, 90000 if lap > 1 else 0, None, 0.0)
            out2.append({"args": [lap, 0, f, 90000 if lap > 1 else 0, None, 0.0], "snap": snap_clean(st2.snapshot())})
    return {"steps": steps, "free_run": out2}

class Clock:
    t = 1000.0
    def time(self): return self.t

def events_case():
    clk = Clock()
    udp.time = types.SimpleNamespace(time=clk.time, monotonic=clk.time, sleep=lambda s: None)
    fired = []
    for name in ("pause", "resume", "race_start", "race_end"):
        udp.register_event(name, lambda p, n=name: fired.append(n))
    def pk(**kw):
        base = {"paused": False, "car_on_track": True, "loading": False, "speed_kmh": 0.0, "lap_number": 1, "total_laps": 3}
        base.update(kw); return base
    seq = [
        # (dt, packet kwargs)
        (0.0, dict(loading=True)),
        (0.5, dict(loading=False)),                     # arms grid start
        (0.1, dict(speed_kmh=0.0)),                     # grid start -> race_start
        (1.0, dict(speed_kmh=50.0)),
        (1.0, dict(paused=True, speed_kmh=50.0)),       # pause
        (1.0, dict(paused=False, speed_kmh=50.0)),      # resume
        (1.0, dict(lap_number=2, speed_kmh=150.0)),
        (1.0, dict(lap_number=4, speed_kmh=150.0)),     # race_end
        (3.0, dict(lap_number=4, speed_kmh=150.0)),     # stays quiet (race over)
        (1.0, dict(lap_number=1, total_laps=3, speed_kmh=100.0)),   # rolling start arming
        (1.0, dict(lap_number=1, total_laps=3, speed_kmh=100.0)),
        (1.5, dict(lap_number=1, total_laps=3, speed_kmh=100.0)),   # race_start (rolling)
        (0.5, dict(loading=True, speed_kmh=0.0)),
        (0.6, dict(loading=True, speed_kmh=0.0)),
        (0.6, dict(loading=True, speed_kmh=0.0)),       # abandon -> race_end
    ]
    out = []
    for dt, kw in seq:
        clk.t += dt
        n0 = len(fired)
        p = pk(**kw)
        udp._check_events(p)
        out.append({"t": clk.t, "packet": p, "fired": fired[n0:]})
    return out

def main(path):
    json.dump({"stint": stint_case(), "events": events_case()}, open(path, "w"), indent=1, sort_keys=True)
    print("wrote", path)
main(sys.argv[1])
